namespace sv_443756c738844f29b0238b832912785d.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Each user session gets its own instance, ensuring independent state.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnWarehouseChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Harbor"),
    ];
}

public record WarehouseInfo(string Id, string Name);

namespace sv_443756c738844f29b0238b832912785d.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each circuit gets its own instance with independent polling state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _currentAlertCount;

    public int CurrentAlertCount => _currentAlertCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query for items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Subscribe to polling. Polling starts when the first subscriber joins.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    /// <summary>
    /// Unsubscribe from polling. Polling stops when the last subscriber leaves.
    /// </summary>
    public void Unsubscribe()
    {
        _subscriberCount--;
        if (_subscriberCount <= 0)
        {
            _subscriberCount = 0;
            StopPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Immediately fetch on start
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAsync()
    {
        _currentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async void HandleWarehouseChanged()
    {
        // When the warehouse changes, immediately refresh alert data
        await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        StopPolling();
    }
}

