@rendermode InteractiveServer
@using sv_443756c738844f29b0238b832912785d.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-dropdown"><strong>Current Warehouse:</strong></label>
    <select id="warehouse-dropdown" class="form-select form-select-sm" 
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var selected = e.Value?.ToString();
        if (!string.IsNullOrEmpty(selected))
        {
            WarehouseState.SetWarehouse(selected);
        }
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

@rendermode InteractiveServer
@using sv_443756c738844f29b0238b832912785d.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge" title="Low stock alerts">
    @if (AlertService.CurrentAlertCount > 0)
    {
        <span class="badge bg-danger">@AlertService.CurrentAlertCount</span>
    }
    else
    {
        <span class="badge bg-success">0</span>
    }
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span> Alerts
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        // The sidebar badge subscribes so polling stays active while it's visible
        AlertService.Subscribe();
    }

    private void HandleAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        AlertService.Unsubscribe();
    }
}

